import base64

MAGIC = b"DHTB"
HEADER_SIZE = 0x200
TOTAL_SIZE_FIELD_OFFSET = 0x30
UBOOT_SIZE_FIELD_OFFSET = 0x38

TABLE_SIZE = 96
TEE_PAD = 8

PAD_ALIGN = 0x1000       # 4096
PAD_BYTE = 0xFF

_HEADER_B64 = (
    ""
)

_TEE_BLOCK_B64 = (
    ""
)

_SIGNATURE_B64 = (
    ""
)

HEADER = base64.b64decode(_HEADER_B64)
TEE_BLOCK = base64.b64decode(_TEE_BLOCK_B64)
SIGNATURE = base64.b64decode(_SIGNATURE_B64)

assert HEADER[0:4] == MAGIC, "The template header magic doesn't match!"
assert len(HEADER) == HEADER_SIZE
assert len(TEE_BLOCK) == 776
assert len(SIGNATURE) == 564
